export function translate(key,lang='pt',params={}){
 const row=messages[key];
 if(!row)throw new Error('Missing translation: '+key);
 const template=row[locales.indexOf(lang)]??row[0];
 return template.replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??''));
}
export function localizeTask(task,lang){
 return {...task,title:task.title.startsWith('Revise: ')?translate('reviewSection',lang,{section:translate(task.title.slice(8),lang)}):translate(task.title,lang),reason:translate(task.reason,lang),action:translate(task.action,lang)};
}
